style.css:
@-moz-document domain("natomanga.com") {
@media (min-width: 1200px) {
    .container {
        max-width: 1260px;
    }
}

.leftCol {
    width: calc(100% - 390px);
}

.middleCol {
    width: 380px;
}

.sts {
    font-size: 16px;
    text-transform: none;
}

.itemupdate ul li h3 {
    max-width: 100%;
}

.itemupdate ul li h3 a {
    font-size: 16px;
    text-transform: none;
}

.itemupdate i {
    font-size: 12px;
}

.cover img {
    width: 101px;
    height: 141px;
}

.itemupdate ul{
    height: 100%;
}

.itemupdate ul li:nth-child(1) {
    margin-bottom: 12px;
}

.banner-cus {
    display: none;
}

.info-top-chapter-text {
    display: none;
}

.info-top-chapter h2 {
    display: none;
}

.current-chapter{
    display: none;
}

.new_update_trangdoc{
    display: none;
}
}
